function formatPlotNumbers(text) {
    if (!text || text.trim() === '') return '-';

    var html = '';
    for (var i = 0; i < text.length; i++) {
        html += text[i];

        if ((i + 1) % 27 === 0) {
            html += '<br>';
        }
    }
    return html;
}
